import{_ as p,a0 as o,w as r,s as d,I as a,x as t,a1 as i,A as l,ao as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"安装 elementary OS 6 “Odin” 后要做的 10 件事 | LCTT x X-CMD","titleTemplate":false,"description":"安装 elementary OS 6 “Odin” 后要做的 10 件事 | LCTT (202109) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"安装 elementary OS 6 “Odin” 后要做的 10 件事 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"安装 elementary OS 6 “Odin” 后要做的 10 件事 | LCTT (202109) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202109/20210821 10 Things to Do After Installing elementary OS 6 -Odin","title":"安装 elementary OS 6 “Odin” 后要做的 10 件事","tag":"202109","desc":""},"relativePath":"202109/20210821 10 Things to Do After Installing elementary OS 6 -Odin.md","filePath":"[post].md"}'),h={name:"202109/20210821 10 Things to Do After Installing elementary OS 6 -Odin.md"};function u(m,e,g,b,k,f){const n=o("Link");return r(),d("div",null,[e[27]||(e[27]=a("h1",{id:"安装-elementary-os-6-odin-后要做的-10-件事",tabindex:"-1"},[t("安装 elementary OS 6 “Odin” 后要做的 10 件事 "),a("a",{class:"header-anchor",href:"#安装-elementary-os-6-odin-后要做的-10-件事","aria-label":"Permalink to “安装 elementary OS 6 “Odin” 后要做的 10 件事”"},"​")],-1)),e[28]||(e[28]=a("blockquote",null,[a("p",null,"一个精心准备的在安装 elementary OS 6 “Odin” 后要做的事情的列表。")],-1)),e[29]||(e[29]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/202109/04/081345bf9co7ot40szdytg.jpg",alt:""})],-1)),a("p",null,[e[1]||(e[1]=t("在经过两年多的开发后 ",-1)),i(n,{href:"https://www.debugpoint.com/2021/08/elementary-os-6/"},{default:l(()=>[...e[0]||(e[0]=[t("elementary OS 6 “Odin”",-1)])]),_:1}),e[2]||(e[2]=t(" 于不久前发布，此次版本更新在核心模块、 Pantheon 桌面、原生应用方面带来了一大批新特性。elementary OS 6 “Odin” 是基于 Ubuntu 20.04 LTS 的。",-1))]),e[30]||(e[30]=s(`<p>如果你完成了安装，你可能想要尝试通过一些特定的设置来使你的系统更加的个性化。这里描述的选项是通用的，在某些情况下可能对你没有用，但是我们觉得有必要列出一些基本的东西，让你有合适的方式来探索这个漂亮的 elementary OS。</p><h3 id="安装完-elementary-os-6-odin-后要做的事情" tabindex="-1">安装完 elementary OS 6 “Odin” 后要做的事情 <a class="header-anchor" href="#安装完-elementary-os-6-odin-后要做的事情" aria-label="Permalink to “安装完 elementary OS 6 “Odin” 后要做的事情”">​</a></h3><p>准备步骤：</p><p>首先确保你已经连上了互联网，你可以在顶部的通知区域查看可用的网络列表</p><h4 id="_1、更改主机名" tabindex="-1">1、更改主机名 <a class="header-anchor" href="#_1、更改主机名" aria-label="Permalink to “1、更改主机名”">​</a></h4><p>这可能不是你想做的第一件事。但是我不知道为什么在安装过程中没有给出更改主机名的选项。例如，见下图的终端提示， 这个主机名是 elementary OS 的默认硬件配置。在我看来这一点都不好。</p><p><img src="https://www.debugpoint.com/blog/wp-content/uploads/2021/08/hostname-change-before.jpeg" alt="主机名修改之前"></p><p>打开终端并运行下列命令以更改主机名：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>hostnamectl set-hostname your-new-hostname</span></span></code></pre></div><p>示例：</p><p><img src="https://www.debugpoint.com/blog/wp-content/uploads/2021/08/changing-hostname.jpeg" alt="修改主机名"></p><p><img src="https://www.debugpoint.com/blog/wp-content/uploads/2021/08/changed-hostname.jpeg" alt="主机名修改之后"></p><h4 id="_2、升级你的系统" tabindex="-1">2、升级你的系统 <a class="header-anchor" href="#_2、升级你的系统" aria-label="Permalink to “2、升级你的系统”">​</a></h4><p>在安装任何 Linux 发行版后，你应该做的第一件事就是确保系统处于最新的软件包和安全更新状态。</p><p>你可以通过打开应用中心来检查或者安装更新。</p><p>或者打开终端运行下列命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt update</span></span>
<span class="line"><span>sudo apt upgrade</span></span></code></pre></div><h4 id="_3、安装-pantheon-tweaks" tabindex="-1">3、安装 Pantheon Tweaks <a class="header-anchor" href="#_3、安装-pantheon-tweaks" aria-label="Permalink to “3、安装 Pantheon Tweaks”">​</a></h4><p>Pantheon Tweaks 是 elementary OS 的必备应用。它提供了一些无法通过系统原生设置程序修改的额外的设置和配置选项，请打开终端并运行以下命令以安装 Pantheon Tweaks。注意：先前版本的 Tweak 工具叫做 elementary Tweaks，从 Odin 版本开始更名为 Pantheon Tweaks。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install software-properties-common</span></span>
<span class="line"><span>sudo add-apt-repository -y ppa:philip.scott/pantheon-tweaks</span></span>
<span class="line"><span>sudo apt install -y pantheon-tweaks</span></span></code></pre></div><p>安装后打开系统设置，你可以在那里找到 “<ruby>调整<rt>Tweaks</rt></ruby>” 选项。</p>`,21)),a("p",null,[i(n,{href:"https://www.debugpoint.com/2021/07/elementary-tweaks-install/"},{default:l(()=>[...e[3]||(e[3]=[t("这里",-1)])]),_:1}),e[4]||(e[4]=t(" 提供了更详细的安装指南（如果你需要了解更多信息）。",-1))]),e[31]||(e[31]=s('<h3 id="_4、配置-dock" tabindex="-1">4、配置 Dock <a class="header-anchor" href="#_4、配置-dock" aria-label="Permalink to “4、配置 Dock”">​</a></h3><p>Dock 是整个桌面的中心。老实说，Dock 中默认包含的应用并不常用，因此你可以通过以下步骤配置 Dock 中的项目。</p><ul><li>移除：右键单击并取消 “<ruby>在 Dock 中驻留<rt>Keep in Dock</rt></ruby>” 选项。</li><li>添加新的项目：单击顶部的应用程序。然后右键单击你想要放在 Dock 的应用图标。选择 “<ruby>添加到 Dock<rt>Add to Dock</rt></ruby>”。</li></ul><p>在我看来，你应该至少把文件管理、截图工具、Firefox 、计算器，以及其他的一些应用添加到 Dock。然后移除 Dock 上那些你不需要的应用。</p><h4 id="_5、更改外观" tabindex="-1">5、更改外观 <a class="header-anchor" href="#_5、更改外观" aria-label="Permalink to “5、更改外观”">​</a></h4><p>elementary OS 6 Odin 改进了桌面的整体外观，为整个桌面和应用程序提供了自带的强调色和原生的夜间模式，同时，系统自带了许多漂亮的壁纸。你可以通过 “应用 &gt; 系统设置 &gt; 桌面” 来定制壁纸、外观、面板和多任务视图。</p><p><img src="https://www.debugpoint.com/blog/wp-content/uploads/2021/08/elementary-OS-6-Odin-settings-window-Desktop.jpeg" alt="elementary OS 6 Odin 桌面设置界面"></p><p>按照你希望的样子来配置你系统的外观。</p><p>你也可以基于日出和日落的时间来设置夜间模式。</p><h4 id="_6、安装其他的应用" tabindex="-1">6、安装其他的应用 <a class="header-anchor" href="#_6、安装其他的应用" aria-label="Permalink to “6、安装其他的应用”">​</a></h4><p>自带的应用中心非常适合这个系统，我发现它是 Linux 桌面最好的应用商店之一。然而，有时候需要安装没有预装的必要应用（大多数是知名的应用）。下面是个新系统推荐安装的软件列表。（说真的，为什么 LibreOffice 没有预装？）</p><ul><li>firefox</li><li>gimp</li><li>gedit</li><li>inkscape</li><li>obs-studio</li><li>libreoffice</li></ul><h4 id="_7、一些针对笔记本电脑的省电贴士" tabindex="-1">7、一些针对笔记本电脑的省电贴士 <a class="header-anchor" href="#_7、一些针对笔记本电脑的省电贴士" aria-label="Permalink to “7、一些针对笔记本电脑的省电贴士”">​</a></h4><p>有许多方法可以配置你的 elementary OS（或者一般的 Linux 桌面），以达到延长电池寿命的目的。记住，电池寿命取决于你的笔记本硬件，以及电池和笔记本的使用年限。所以，遵循下面的一些建议，最大限度的利用你的笔记本电池。</p>',14)),a("ul",null,[a("li",null,[a("p",null,[e[6]||(e[6]=t("安装 ",-1)),i(n,{href:"https://linrunner.de/tlp/"},{default:l(()=>[...e[5]||(e[5]=[t("tlp",-1)])]),_:1}),e[7]||(e[7]=t("。",-1)),e[8]||(e[8]=a("code",null,"tlp",-1)),e[9]||(e[9]=t(" 是一个简单易用的命令行程序，用来帮你在 Linux 上延长电池寿命。你只需要安装它，默认情况下，它会处理好其他的设置。安装命令：",-1))]),e[10]||(e[10]=s(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo add-apt-repository ppa:linrunner/tlp</span></span>
<span class="line"><span>sudo apt update</span></span>
<span class="line"><span>sudo apt-get install tlp</span></span>
<span class="line"><span>sudo tlp start</span></span></code></pre></div>`,1))]),e[11]||(e[11]=s('<li><p>关闭蓝牙，默认情况下，蓝牙是开启状态。在需要的时候再启动它。</p></li><li><p>通过下面的命令安装 <code>thermald</code>。这个实用程序（实际是个守护进程）控制着你的 CPU 的 P-States 和 T-States 的温度以及 CPU 发热。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install thermald</span></span></code></pre></div></li><li><p>根据你的需要将亮度调到最小。</p></li>',3))]),e[32]||(e[32]=s('<h4 id="_8、安装磁盘实用程序" tabindex="-1">8、安装磁盘实用程序 <a class="header-anchor" href="#_8、安装磁盘实用程序" aria-label="Permalink to “8、安装磁盘实用程序”">​</a></h4><p>在很多情况下，你发现你需要格式化 USB 或者向 USB 中写入一些东西。默认情况下，系统没有安装任何相关的应用。你可以安装以下这些易用的应用。</p><ul><li>gnome-disk-utility</li><li>gparted</li></ul><h4 id="_9、启用最大化和最小化选项" tabindex="-1">9、启用最大化和最小化选项 <a class="header-anchor" href="#_9、启用最大化和最小化选项" aria-label="Permalink to “9、启用最大化和最小化选项”">​</a></h4><p>许多用户喜欢在窗口标题栏左边或者右边使用最大化、最小化的按钮，elementary OS 默认只提供关闭和恢复两个选项。这没什么问题，因为这就是它的设计理念。然而你可以通过使用 Pantheon Tweaks 来开启最大化和最小化按钮，具体的方式是：“调整 &gt; 外观 &gt; 窗口控制”。</p><p><img src="https://www.debugpoint.com/blog/wp-content/uploads/2021/08/enable-minimize-maximize-buttons-elementary-OS-1024x501.png" alt="在 elementary OS 中启动最大化和最小化设置"></p><h4 id="_10、在-odin-中学习新的多点触控手势" tabindex="-1">10、在 Odin 中学习新的多点触控手势 <a class="header-anchor" href="#_10、在-odin-中学习新的多点触控手势" aria-label="Permalink to “10、在 Odin 中学习新的多点触控手势”">​</a></h4><p>如果你是笔记本用户，并且使用 elementary OS “Odin”，那么你一定要看看这些超酷的新触控手势。三根手指向上滑动，就会平滑的打开多任务视图，展示打开的应用程序和工作空间。用三根手指向左或向右滑动，就能在动态工作空间之间流畅的切换，使任务之间的切换更快。</p><p>用两根手指也可以在原生应用中实现类似的功能。</p><h3 id="结束语" tabindex="-1">结束语 <a class="header-anchor" href="#结束语" aria-label="Permalink to “结束语”">​</a></h3><p>我希望这篇安装 elementary OS 6 “Odin” 后要做的 10 件事能帮助到你，让你可以上手使用 elementary OS 6 “Odin”，尽管这些事情完全是用户的偏好，因此这些事情有可能适合你也有可能不适用于你，但总的来说，这些都是一般用户喜欢的预期调整。</p><p>如果你觉得有更多的东西应该添加到列表中，请在下面的评论中告诉我。</p><hr>',13)),a("p",null,[e[13]||(e[13]=t("via: ",-1)),i(n,{href:"https://www.debugpoint.com/2021/08/10-things-to-do-after-install-elementary-os-6/"},{default:l(()=>[...e[12]||(e[12]=[t("https://www.debugpoint.com/2021/08/10-things-to-do-after-install-elementary-os-6/",-1)])]),_:1})]),a("p",null,[e[18]||(e[18]=t("作者：",-1)),i(n,{href:"https://www.debugpoint.com/author/admin1/"},{default:l(()=>[...e[14]||(e[14]=[t("Arindam",-1)])]),_:1}),e[19]||(e[19]=t(" 选题：",-1)),i(n,{href:"https://github.com/lujun9972"},{default:l(()=>[...e[15]||(e[15]=[t("lujun9972",-1)])]),_:1}),e[20]||(e[20]=t(" 译者：",-1)),i(n,{href:"https://github.com/anine09"},{default:l(()=>[...e[16]||(e[16]=[t("anine09",-1)])]),_:1}),e[21]||(e[21]=t(" 校对：",-1)),i(n,{href:"https://github.com/wxy"},{default:l(()=>[...e[17]||(e[17]=[t("wxy",-1)])]),_:1})]),a("p",null,[e[24]||(e[24]=t("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...e[22]||(e[22]=[t("LCTT",-1)])]),_:1}),e[25]||(e[25]=t(" 原创编译，",-1)),i(n,{href:"https://linux.cn/"},{default:l(()=>[...e[23]||(e[23]=[t("Linux中国",-1)])]),_:1}),e[26]||(e[26]=t(" 荣誉推出",-1))])])}const O=p(h,[["render",u]]);export{w as __pageData,O as default};
